"""Render the retrospective macro report and compact website payload from statistics.json."""
from pathlib import Path
import hashlib, json, platform, shutil

R=Path(__file__).resolve().parents[1];D=R/'analysis/macro-patterns'
s=json.loads((D/'statistics.json').read_text())
for p,h in s['input_sha256'].items():assert hashlib.sha256((R/p).read_bytes()).hexdigest()==h
def short(m):return m.replace('gpt-','').replace('-sol',' Sol')
def pct(v):return f'{100*v:.1f}%'
def f(v):return f'{v:.4f}'
def table(headers,rows):return '| '+' | '.join(headers)+' |\n| '+' | '.join(['---']*len(headers))+' |\n'+''.join('| '+' | '.join(map(str,r))+' |\n' for r in rows)
pair=s['pairwise'];p61=next(p for p in pair if p['older']=='gpt-6-sol' and p['newer']=='gpt-6.1-sol')
mainrows=[];senrows=[]
for p in pair:
    a=p['descriptive_denominator'];d=p['main_conservative'];c=a['slice_counts'];lo,hi=a['family_composition_bootstrap_percentile95']
    mainrows.append([short(p['older'])+' → '+short(p['newer']),c.get('win',0),c.get('loss',0),c.get('tie',0),c.get('failed_or_missing',0),f(a['task_equal_win_fraction']),f(a['family_equal_win_fraction']),f(d['family_equal_net_direction']),f(d['exact_family_signflip_two_sided_p']),f(d['holm_adjusted_p_three_version_pairs'])])
    for variant,label in [('observed__all_submissions__denominator','Observed, all attempted'),('observed__all_submissions__complete_cases','Observed, pair complete cases'),('observed__strict__denominator','Observed, pair strict'),('synthetic_inclusive__all_submissions__denominator','Synthetic-inclusive')]:
        v=p['variants'][variant];senrows.append([short(p['older'])+' → '+short(p['newer']),label,v['n_tasks'],v['n_families'],v['n_slices'],f(v['family_equal_win_fraction'])])
    v=p['common_three_model_strict'];senrows.append([short(p['older'])+' → '+short(p['newer']),'Common all-three strict complete support',v['n_tasks'],v['n_families'],v['n_slices'],f(v['family_equal_win_fraction'])])
refrows=[]
for cls in ['conventional_baseline','conventional_domain_reference','historical_specialist','local_specialist','pretrained_specialist']:
    rs=[next(r for r in s['reference_strata'] if r['reference_class']==cls and r['model']==m) for m in s['model_order']]
    refrows.append([cls.replace('_',' '),rs[0]['n_tasks'],rs[0]['n_slices']]+[f(r['task_equal_win_fraction']) for r in rs])
cal=s['case_studies']['C06'];b01=s['case_studies']['B01'];ez=s['case_studies']['E06']
e=lambda m,sl:next(r['mse'] for r in ez if r['model']==m and r['slice_id']==sl)
main_change=(e('gpt-6.1-sol','batch-v11')/e('gpt-6-sol','batch-v11')-1)*100
taxis_change=(e('gpt-6.1-sol','taxis')/e('gpt-6-sol','taxis')-1)*100
quant=[
dict(id='Q1',title='GPT-6.1 has a directional advantage on this panel, with substantial uncertainty',status='Descriptive signal; general superiority unestablished',text=f"Against GPT-6: 23 wins, seven losses and one failed comparison across 31 slices from 24 tasks in 13 families. Family-equal win fraction {f(p61['descriptive_denominator']['family_equal_win_fraction'])}; task-equal fraction {f(p61['descriptive_denominator']['task_equal_win_fraction'])}. Penalizing the newer-only failure gives signed family contrast {f(p61['main_conservative']['family_equal_net_direction'])}. Exact conditional sign-flip p={f(p61['main_conservative']['exact_family_signflip_two_sided_p'])}; Holm-adjusted p=1.0000. Neither significance nor no-effect is established."),
dict(id='Q2',title='The version sequence is not a monotonic improvement law',status='Exact panel description',text='Among 30 slices where all three models produced numerical scores, only nine improve monotonically (allowing a numerical tie), and six of 23 complete tasks do so on every slice. GPT-6.1 is best or numerically tied-best on 20 slices but worse than both older models on five. Missing J08 is excluded from these complete-case counts. Version names do not provide compute, parameter-count or training-data measurements.'),
dict(id='Q3',title='Reference strata produce different apparent win rates',status='Descriptive; confounded by task and reference selection',text='Task-equal point-win fractions against conventional baselines are 0.7500 / 0.8333 / 0.8333 for 5.6 / 6 / 6.1 (12 tasks). Against archived specialists they are 0.3000 / 0.2500 / 0.6500 (four tasks); local specialists give 0.6000 / 0.6000 / 0.8000 (five tasks). These are different task sets, with unequal inputs and optimization histories. This is not a causal effect of specialist status, and GPT-6.1’s local-specialist rate is close to its conventional-baseline rate.'),
]
quant.append(dict(id='Q4',title='Cell and molecular tasks show the most consistent multi-task category signal',status='Retrospective category observation; hypothesis for replication',text='GPT-6.1 beats both older versions on all four measured cell/molecular tasks: K01 morphology classification, K04 cortical-layer transfer, K05 marker-fraction calibration and K06 PV/SST waveform classification. These four are strict-format common support. This is the largest category with an all-task directional advantage for GPT-6.1 in the observed panel. It does not establish a modality law: broad source collections overlap, tasks were selected for feasibility, and K01 has a small native margin. SingleR still beats GPT-6.1 on K04 (0.5546 vs 0.5506). No category-specific significance claim is made after inspecting all categories.'))
qual=[
dict(id='L1',title='The tested capability is building analysis procedures',status='Scope interpretation',text='All three Sol models generate numerical programs that are then fitted locally. Their wins support trying a generated algorithm baseline on a well-defined numeric endpoint. They do not establish native raw neural-data perception, general multimodal/world-model skill, autonomous experiment execution or specialist-tool-agent performance.'),
dict(id='L2',title='A benchmark name does not specify the information contract',status='Protocol interpretation',text='Custom slices provide processed waveforms, calcium traces, pose features, expression columns, known simulator equations or small storage chunks. Supervised K05 fraction calibration differs from reference-only deconvolution; likelihood-informed L06 differs from simulator-only inference; E06 uses a subset and locally optimized NLinear. Those distinctions can explain what is feasible, but this panel cannot estimate their causal effect.'),
dict(id='L3',title='Biological replication remains the main evidence gap',status='Unmeasured uncertainty',text='Examples include one held-out bird in A15, two test fish in C06, one brain/session in E06 and one monkey shared by G01/B08. Many cells, frames or windows do not create independent cohorts. Most tasks have one code generation. Category resampling cannot recover missing animal, lab, generation or prompt uncertainty.'),
]
combined=[
dict(id='C1',title='Metric choice can reverse which model looks better',status='Quantitative case evidence plus scientific interpretation',text='C06 GPT-6.1 has higher correlation than GPT-5.6 (0.8676 vs 0.8564), but worse relative count error (3.2471 vs 1.9040). In B01, GPT-6 exceeds GPT-5.6 on the frozen unit metric (0.9400 vs 0.8750), but falls below it on post-hoc all-output event F1 (0.5998 vs 0.9000). Two of three B01 pairwise model orderings reverse. Calibration and extra events affect scientific use; a single primary leaderboard value cannot establish those properties.'),
dict(id='C2',title='Within-condition improvement does not guarantee transfer',status='One controlled source-shift case; hypothesis for replication',text=f'On E06, GPT-6.1 reduces MSE versus GPT-6 by {-main_change:.1f}% on temporal tails, but increases it by {taxis_change:.1f}% on the prespecified unseen-taxis slice. The same programs, training arrays, neurons and brain are used; native target distributions differ. This is a real ordering reversal, not proof of a universal transfer law or a causal mechanism.'),
dict(id='C3',title='Failure definitions and reproducibility matter to the conclusion',status='Direct procedural evidence',text='The panel has 107 numerical successes in 111 model attempts, but only 100 meet the line-format criterion as well. Two B08 failures arise from ambiguous utility-import wording and stay visible while the task is excluded from aggregate claims. J08’s GPT-6.1 numerical failure remains a loss in the conservative diagnostic. H02’s three attempts per model are separate evidence on one source, not extra independent tasks.'),
]
conclusion='There are useful descriptive signals, especially a GPT-6.1 directional advantage and metric/source-shift reversals. This panel establishes no universal improvement law, no reliable causal predictor of generalist success, and no general-model victory over current strongest specialists. Failure to reject the family-level null does not show that all variation is noise.'
report=f'''# Macro patterns in Neural Data Bench

Retrospective analysis revision 2026-10-31-v12. **No new benchmark or model run.** Measurement snapshot 0.11: 30 tasks across 14 families, 37 slices/model, 111 model attempts and 208 model/reference rows. The [quick audit](../quick-audit-v12.json) checks all 200 successful records and preserves eight original failed rows (four model failures, four archived-reference failures).

{conclusion}

## How the analysis is organized

The requested buckets are **quantitative**, **qualitative**, and **quantitative + qualitative**. Each finding below distinguishes a panel fact, an assumption-dependent statistical diagnostic and an interpretation. This is a retrospective synthesis, not a preregistered discovery study. Public labels, convenience selection, shared sources and one generation per task limit inference. [Methods](methods.md), [machine-readable statistics](statistics.json), [task context](task-context.csv), [native paired margins](paired-slices.csv).

![Macro patterns and benchmark-composition sensitivity](macro-patterns.png)

The left intervals resample the 13 benchmark families 20,000 times. They describe benchmark-composition sensitivity, not biological or code-generation confidence. The 0.5 line is a descriptive reference; ties and failures prevent treating it as a calibrated null. Reference strata on the right contain different tasks and unequal budgets; their differences are not causal.

## Quantitative findings

'''
for x in quant:report+=f"### {x['id']}. {x['title']}\n\n**{x['status']}.** {x['text']}\n\n"
report+='### Model-version diagnostics\n\n'+table(['Contrast','Wins','Losses','Ties','Missing/failed','Task-equal wins','Family-equal wins','Conservative signed contrast','Conditional p','Holm p (3)'],mainrows)
report+='\nThe signed contrast averages +1 for a newer win and −1 for a newer loss within task, then within family, then equally across families. A newer-only numerical failure counts as −1; an older-only failure +1; both failed zero. No numerical score is invented. Sign-flip p-values enumerate all 8,192 family sign patterns under an assumed symmetric independent-family null. The taxonomy and observations do not establish that assumption. The three main contrasts receive Holm adjustment; other analyses are sensitivities, not additional confirmatory discoveries. All adjusted p-values are 1.0.\n\n'
report+='### Sensitivity to inclusion and compliance\n\n'+table(['Contrast','Scope / policy','Tasks','Families','Slices','Family-equal wins'],senrows)
report+='\nCommon-support strict results use the same 20 tasks / 12 families / 23 slices for every pair. Pair-specific strict results use different panels; they must not be directly ranked as if only compliance changed. Complete-case exclusion removes the sole family-J task for comparisons involving GPT-6.1, explaining part of its higher fraction. Synthetic-inclusive summaries still exclude M04, N05 and ambiguous B08.\n\n'
a=p61['descriptive_denominator'];d=p61['main_conservative'];lo,hi=a['family_composition_bootstrap_percentile95']
report+=f"For 6.1 versus 6, omitting any one family leaves the family-equal win fraction between {f(a['leave_one_family_win_range'][0])} and {f(a['leave_one_family_win_range'][1])}. The family-composition interval is [{f(lo)}, {f(hi)}]. The conservative signed contrast also stays positive under every single-family omission. This direction is not caused by only one category, but simultaneous family changes and unmeasured generation/source uncertainty remain substantial. The historical missing-as-neutral diagnostic yields p={f(a['exact_family_signflip_two_sided_p'])}, adjusted {f(a['holm_adjusted_p_three_version_pairs'])}; it also supplies no rejection.\n\n"
report+='### Reference evidence strata\n\n'+table(['Declared class','Tasks','Slices','5.6 win fraction','6 win fraction','6.1 win fraction'],refrows)
report+='\nSlices are averaged within task. Strict variants and family-weighted values are in statistics.json. The [complete category scan](category-signals.csv) reports every family and all three contrasts, including negative and neutral task counts; Q4 is not an independently selected confirmatory hypothesis. The pretrained stratum contains only Sleep-EDF/YASA; it cannot establish a class-wide pattern. C05 uses a test-selected historical envelope; H01 permits explicit post-hoc alignment; local OASIS is not strongest CASCADE; other baseline/local/historical optimization histories vary. None certifies current global SOTA.\n\n'
report+='## Qualitative findings\n\n'
for x in qual:report+=f"### {x['id']}. {x['title']}\n\n**{x['status']}.** {x['text']}\n\n"
report+='## Quantitative + qualitative findings\n\n'
for x in combined:report+=f"### {x['id']}. {x['title']}\n\n**{x['status']}.** {x['text']}\n\n"
report+='### Calcium calibration: native numbers\n\n'+table(['Procedure','Fish-equal Pearson ↑','Relative count error ↓','Signed relative count bias'],[[short(r['model']),f(r['pearson']),f(r['relative_count_error']),f(r['signed_relative_count_bias'])] for r in cal])
report+='\nThe paired-*.csv exports explicitly label the historical missing-as-neutral descriptive policy. Main diagnostic rows are in [main-conservative-slices.csv](main-conservative-slices.csv), [main-conservative-tasks.csv](main-conservative-tasks.csv) and [main-conservative-families.csv](main-conservative-families.csv).\n\nRelative count error is absolute predicted-versus-true total-count difference divided by true count, averaged equally over neurons within fish and then over fish. It is a ratio, not percentage points or per-bin error; 1.9040 is about 190.4% relative error. Signed bias is separately averaged, so cancellation is possible. Both are predeclared secondary diagnostics; Pearson remains the primary. B01 event F1 is post-hoc and never replaces its frozen primary.\n\n'
report+='## What is not established, and what to do next\n\nNo scaling law is fitted: three model labels do not provide model size, compute or training-data quantities, and progress is not monotonic. No task-difficulty or modality success predictor is fitted: 24 heterogeneous task endpoints, confounded references and few independent sources cannot support a stable moderator model. Non-rejection is not equivalence and does not prove noise. Native deltas remain in their units; tiny point wins have no retrospectively invented practical-equivalence threshold.\n\nFor a lab, the evidence supports generating a cheap baseline when the numeric interface and validation contract are explicit, then checking the property the science needs: calibration, extra events, unseen-condition transfer or exact reconstruction. Keep the strongest feasible matched specialist and inspect saved outputs. This is a practical interpretation, not a tested cost-effectiveness or deployment recommendation.\n\nThe most informative next experiment is a fixed diverse panel with repeated generations and independently held-out sources, a priori meaningful endpoint margins and strong specialists with matched inputs and tuning budgets. Replicate the C06 calibration and E06 shift reversals on new sources. Keep H02 repetitions separate until other tasks have comparable generation depth.\n\n## Traceability and research basis\n\n- [Statistical procedure and assumptions](methods.md); [all task context and limits](task-context.csv); [independent review](independent-review.md).\n- [Pair slices and native margins](paired-slices.csv), [task summaries](paired-tasks.csv), [family summaries](paired-families.csv), [reference comparisons](reference-slices.csv), [three-model ranks](three-model-ranks.csv), [monotonicity rows](monotonic-slices.csv).\n- Original [central ledger](../../results/measurements.jsonl), [protocols](../../experiments), [macro policy](../../docs/macro-analysis-plan.md).\n- Demšar (2006), [Statistical Comparisons of Classifiers over Multiple Data Sets](https://jmlr.org/papers/v7/demsar06a.html), motivates comparing dimensionless ranks across datasets rather than mixing arbitrary native metrics. This report uses a separately specified family sign-flip diagnostic because task families and shared slices require explicit grouping; it does not claim to implement all of that paper’s procedure.\n- Agarwal et al. (2021), [Deep Reinforcement Learning at the Edge of the Statistical Precipice](https://proceedings.neurips.cc/paper_files/paper/2021/hash/f514cec81cb148559cf475e7426eed5e-Abstract.html), motivates uncertainty-aware benchmark reporting. Its repeated-run inference is not available from our mostly single-generation panel; family-composition resampling is labeled accordingly.\n'
(D/'report.md').write_text(report)
methods='''# Macro analysis methods

This is an explicitly retrospective analysis of measurement snapshot 0.11. The script reads the exact frozen central ledger and summary, records their SHA256s, and checks they remain unchanged. It does not call models, alter submissions, fit references or rescore scientific outputs.

## Units, scopes and outcomes

Observed scope excludes B01/B03/L06/M04 (fully synthetic), N05 (deterministic correctness) and B08 (ambiguous utility-import contract). A14/H16 observed sources with artificial corruption remain included. That leaves 24 tasks, 13 families and 31 slices; not 24 independent biological cohorts. Synthetic-inclusive scope restores B01/B03/L06 but retains M04/N05/B08 exclusions. B08 exclusion was decided in the prior batch after its failure and remains explicitly retrospective.

A valid newer-minus-older metric delta is multiplied by +1 for higher-is-better and −1 for lower-is-better. Above 1e−9 is a point win, below −1e−9 a point loss, otherwise a numerical tie. No practical-equivalence margin was prospectively specified. Raw paired score margins, direction and metric units are exported; incompatible metric sizes are never averaged. Within-slice three-model ranks (1 best, average exact ties) are secondary complete-case descriptions, not another selected hypothesis test.

For directional win fractions, each slice is a win indicator; slices average within task, tasks within family and families equally. Denominator policy retains failed/missing pairs as nonwins, without a numeric score. The main signed diagnostic instead treats a newer-only numerical failure as a loss and older-only failure as a win; both failed is zero. Strict filters use code-format flags and explicitly report their reduced panel. Common-three-model strict complete support prevents pair-dependent panel composition. No source dataset, neuron, frame or parameter is counted as another task.

## Statistical diagnostics

Main statistic: equal-family mean of within-family mean task signed win fractions. Enumerate all 2^13 family sign reversals for a two-sided reference distribution; include null values whose absolute magnitude is at least the observed magnitude (1e−12 floating tolerance). This is exact enumeration under a symmetric independent-family null, not an exact randomized experiment. Family grouping reduces obvious within-category dependence but does not prove between-family independence. The three version contrasts are one retrospective family for Holm step-down adjustment. Alternative scopes, compliance filters, ranks and missingness policies are sensitivity descriptions, not searches for significance; Holm does not correct the entire historical research process.

Family-composition sensitivity: draw 20,000 bootstrap samples of 13 whole families with replacement (NumPy seed 20261031), averaging each sampled family's fixed directional win fraction. The 2.5/97.5 percentiles describe this empirical benchmark composition, not biological population, code-generation, prompt or provider confidence. Leave-one-family-out removes each whole family. These do not replace missing repeated generations or independent source cohorts.

Reference comparisons are stratified by the existing frozen/local/historical reference policy. Failure stays visible. Differences between strata are descriptive because the tasks, sample sizes, information and optimization histories differ. No causal specialist-class effect or current-SOTA advantage is estimated. No normalized native utility, pooled scientific effect, scaling law or moderator regression is fit.

## Reproduction

Run scripts/analyze_macro.py with NumPy, SciPy and Matplotlib, then scripts/write_macro_report.py. Numerical output is deterministic at the pinned seed; graphics/PDF container metadata can vary by library. Run scripts/check_macro.py for a separate standard-library recomputation of the paired counts, family arithmetic and exact conditional p-values. The independent review documents interpretation limits. Requirements in requirements.txt describe the successful runtime; source hashes are in statistics.json.
'''
(D/'methods.md').write_text(methods)
(D/'README.md').write_text('# Macro findings and interpretation\n\nStart with [report.md](report.md): quantitative, qualitative and combined findings, counterexamples, sensitivity analysis and limits. [Methods](methods.md), [statistics](statistics.json), [independent review](independent-review.md), [PNG figure](macro-patterns.png), [PDF figure](macro-patterns.pdf). No new model/benchmark run; snapshot 0.11 unchanged.\n')
import numpy, scipy, matplotlib
(D/'requirements.txt').write_text(f'# Python {platform.python_version()}\nnumpy=={numpy.__version__}\nscipy=={scipy.__version__}\nmatplotlib=={matplotlib.__version__}\n')
payload=dict(revision=s['analysis_revision'],snapshot=s['measurement_snapshot'],title='What patterns survive the checks?',conclusion=conclusion,
             buckets={'quantitative':quant,'qualitative':qual,'combined':combined},
             pairs=[dict(older=p['older'],newer=p['newer'],n_tasks=p['descriptive_denominator']['n_tasks'],n_families=p['descriptive_denominator']['n_families'],n_slices=p['descriptive_denominator']['n_slices'],
                         counts=p['descriptive_denominator']['slice_counts'],family_win=p['descriptive_denominator']['family_equal_win_fraction'],composition_interval=p['descriptive_denominator']['family_composition_bootstrap_percentile95'],
                         conservative_net=p['main_conservative']['family_equal_net_direction'],conditional_p=p['main_conservative']['exact_family_signflip_two_sided_p'],holm_p=p['main_conservative']['holm_adjusted_p_three_version_pairs'],
                         common_strict_win=p['common_three_model_strict']['family_equal_win_fraction']) for p in pair],
             reference_strata=[{k:r[k] for k in ['model','reference_class','n_tasks','n_slices','task_equal_win_fraction']} for r in s['reference_strata']],
             input_sha256=s['input_sha256'],assumptions='Retrospective convenience panel, one program/model/task; grouped tests assume independent symmetric family contrasts. Composition intervals are not biological or generation uncertainty. No global-SOTA or scaling-law claim.')
(R/'website/data/macro-report.json').write_text(json.dumps(payload,indent=2)+'\n');shutil.copyfile(D/'macro-patterns.png',R/'website/data/macro-patterns.png')
print('Report, methods, evidence tables and compact site payload generated from unchanged measurement snapshot.')
